mapper.select:
SELECT * FROM coding_workspace_registry
WHERE project_id = #{projectId}
ORDER BY workspace_ref

mapper.update:
UPDATE coding_workspace_registry
SET location_ref = #{row.locationRef}, safe_display_name = #{row.safeDisplayName},
    source = #{row.source}, status = #{row.status},
    location_nonce = #{row.locationNonce}, location_ciphertext = #{row.locationCiphertext},
    location_digest = #{row.locationDigest}, physical_fingerprint = #{row.physicalFingerprint},
    validated_at_ms = #{row.validatedAt},
    revoked_at_ms = #{row.revokedAt}, revocation_reason_code = #{row.revocationReasonCode},
    version = #{row.version}
WHERE project_id = #{row.projectId} AND workspace_ref = #{row.workspaceRef}
  AND version = #{expectedVersion}
